import {LibraryStore,TYPES,ITEM_TYPES,LEGACY_KEY,uid,stamp,tags,safeUrl,makeGroup,makeItem,blobData,moodboardName} from './data.js?v=small-dialogs-1';
import {AccountCloud} from './cloud.js?v=small-dialogs-1';
import {e,icon,button,empty,date,color,input,textarea,select,checkbox,tagButtons} from './ui.js?v=small-dialogs-1';
const $=s=>document.querySelector(s),root=$('#content'),modal=$('#modal');let store=new LibraryStore(),cloud,accountEpoch=0,legacyOffer=null;
const nav=[['home','홈','home'],['moodboards','무드보드','board'],['collections','취향 컬렉션','collection'],['wishlists','위시리스트','wish'],['buckets','버킷리스트','bucket'],['archive','아카이브','archive']];
const routeType={moodboards:'moodboard',collections:'collection',wishlists:'wishlist',buckets:'bucket'},typeRoute={moodboard:'moodboards',collection:'collections',wishlist:'wishlists',bucket:'buckets'},typeIcon={moodboard:'board',collection:'collection',wishlist:'wish',bucket:'bucket'},typeItem={moodboard:'reference',collection:'taste',wishlist:'product',bucket:'goal'};
let route='home',query='',tag='',category='',sort='manual',groupView='cards',archiveType='all',from='',to='',itemStatus='all',libraryType='all',favoriteOnly=false,canvasMode=false,layoutDraft=null,layoutDirty=false,selectedTile=null,toastTimer,renderEpoch=0,installPrompt=null,blocked=false;
const state=()=>store.state;
const activeItems=()=>state().items.filter(i=>!i.deletedAt);
const activeGroups=()=>state().groups.filter(g=>!g.deletedAt&&!g.archivedAt);
const group=id=>state().groups.find(g=>g.id===id&&!g.deletedAt);
const item=id=>state().items.find(i=>i.id===id&&!i.deletedAt);
const members=g=>g.memberIds.map(item).filter(Boolean);
const locations=id=>activeGroups().filter(g=>g.memberIds.includes(id));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const progress=g=>{const values=members(g);const done=values.filter(i=>i.type==='goal'?i.done:i.purchased).length;return {total:values.length,done,percent:values.length?Math.round(done/values.length*100):0}};
function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function closeSidebar(){const wasOpen=$('#sidebar').classList.contains('open');$('#sidebar').classList.remove('open');$('#sidebarBackdrop').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false');$('.app').inert=false;$('#mobileNav').inert=false;if(wasOpen)$('#menuToggle').focus({preventScroll:true})}
function canLeave(){return !layoutDirty||confirm('저장하지 않은 콜라주 배치가 있어요. 변경을 버리고 이동할까요?')}
function go(target){if(!canLeave())return;layoutDirty=false;layoutDraft=null;canvasMode=false;selectedTile=null;category='';tag='';favoriteOnly=false;itemStatus='all';closeSidebar();if(location.hash==='#'+target){route=target;render()}else location.hash=target}
window.addEventListener('hashchange',()=>{const next=decodeURIComponent(location.hash.slice(1))||'home';if(layoutDirty&&!canLeave()){history.replaceState(null,'','#'+route);return}layoutDirty=false;layoutDraft=null;canvasMode=false;route=next;category='';tag='';favoriteOnly=false;itemStatus='all';closeSidebar();if(store.state)render();window.scrollTo({top:0})});
window.addEventListener('beforeunload',event=>{if(layoutDirty){event.preventDefault();event.returnValue=''}});
async function save(fn,assets=[],message='서랍에 저장했어요.'){if(blocked)throw Error('다른 탭의 변경을 확인한 뒤 새로고침해주세요.');const targetStore=store;await targetStore.mutate(fn,assets);if(targetStore!==store)return;render();notify(message);cloud?.changed()}
function navRender(){const context=route.startsWith('group:')?group(route.slice(6)):null;const addName=context?({moodboard:'사진·메모 추가',collection:'취향 추가',wishlist:'상품 추가',bucket:'목표 추가'})[context.type]:'새 항목 추가';$('#newItem').setAttribute('aria-label',addName);$('#newItem').title=addName;const selected=route.startsWith('group:')?typeRoute[group(route.slice(6))?.type]:route;$('#navigation').innerHTML=nav.map(([id,title,ico])=>`<a href="#${id}" ${selected===id?'class="active" aria-current="page"':''}>${icon(ico)}${title}</a>`).join('');$('#mobileNav').innerHTML=nav.map(([id,title,ico])=>`<a href="#${id}" ${selected===id?'class="active" aria-current="page"':''}>${icon(ico)}<span>${id==='collections'?'컬렉션':title}</span></a>`).join('');$('#folders').innerHTML=activeGroups().filter(g=>g.type==='collection'||g.type==='moodboard').sort((a,b)=>a.order-b.order).map(g=>`<a href="#group:${e(g.id)}" ${route==='group:'+g.id?'class="active"':''}>${icon('folder')}<span>${e(g.title)}</span></a>`).join('')||'<small style="padding:5px 13px">나만의 서랍을 만들어보세요.</small>'}
function imgTag(i,cls='',attr=''){if(i?.imageId)return `<img class="${cls}" data-asset="${e(i.imageId)}" alt="${e(i.title||'')}" loading="lazy" ${attr}>`;if(i?.imageUrl&&safeUrl(i.imageUrl))return `<img class="${cls}" src="${e(safeUrl(i.imageUrl))}" alt="${e(i.title||'')}" loading="lazy" referrerpolicy="no-referrer" ${attr}>`;return ''}
async function hydrate(container=root){const epoch=renderEpoch;await Promise.all([...container.querySelectorAll('img[data-asset]')].map(async img=>{try{const src=await store.src(img.dataset.asset);if(img.isConnected&&(container!==root||epoch===renderEpoch))img.src=src}catch{if(img.isConnected){img.hidden=true;const text=document.createElement('span');text.className='help';text.textContent='이미지를 읽을 수 없어요.';img.after(text)}}}));container.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.hidden=true;if(!img.nextElementSibling?.classList.contains('image-error')){const text=document.createElement('span');text.className='help image-error';text.textContent='이미지를 불러오지 못했어요. 링크를 확인하거나 사진을 직접 올려주세요.';img.after(text)}})}
function itemCard(i,{showLocation=true,showDate=true}={}){const subtitle=showLocation?(locations(i.id).map(g=>g.title).join(' · ')||i.category||ITEM_TYPES[i.type]):i.category||i.brand||(showDate?date(i.createdAt):'');const visual=imgTag(i)||`<div class="no-image ${i.type==='reference'?'quote':''}">${i.cardType==='color'?`<span class="color-chip" style="background:${color(i.color)}"></span>`:''}<h3>${e(i.title)}</h3>${i.note?`<p>${e(i.note.slice(0,150))}</p>`:''}</div>`;return `<article class="item-card" data-id="${e(i.id)}"><button class="item-open" data-action="detail" data-id="${e(i.id)}"><div class="item-visual">${visual}${i.done||i.purchased?`<span class="done-label">${icon('check')} ${i.done?'완료한 경험':'구매 완료'}</span>`:''}</div><div class="item-info"><h3 class="${i.done?'done-title':''}">${e(i.title)}</h3>${i.type==='product'&&i.price!==''&&i.price!=null?`<div class="price">${Number(i.price).toLocaleString('ko-KR')}원</div>`:''}${i.rating?`<span class="rating" aria-label="5점 중 ${Number(i.rating)}점">${'★'.repeat(Math.min(5,Number(i.rating)))}</span>`:''}${subtitle?`<p>${e(subtitle)}</p>`:''}</div></button><button class="card-heart ${i.favorite?'active':''}" data-action="favorite" data-id="${e(i.id)}" aria-label="${e(i.title)} 즐겨찾기" aria-pressed="${!!i.favorite}">${icon('heart')}</button></article>`}
function cover(g){if(g.coverId)return `<img data-asset="${e(g.coverId)}" alt="${e(g.title)} 표지" loading="lazy">`;const images=members(g).filter(i=>i.imageId||i.imageUrl).slice(0,g.type==='moodboard'?3:1);if(images.length)return `<div class="collage-preview">${images.map(i=>`<div>${imgTag(i)}</div>`).join('')}</div>`;return `<div class="preview-placeholder">${icon(typeIcon[g.type])}<span>${({moodboard:'a mood to keep',collection:'little favorites',wishlist:'on my wishlist',bucket:'someday, I will'})[g.type]}</span></div>`}
function groupCard(g){const p=progress(g);return `<article class="group-card" data-id="${e(g.id)}"><button class="group-open" data-action="group" data-id="${e(g.id)}"><div class="group-cover">${cover(g)}</div><div class="group-meta"><h3>${e(g.title)}</h3><p>${g.type==='moodboard'?members(g).filter(i=>i.imageId||i.imageUrl).length+'장의 이미지 · ':''}${g.type==='collection'&&g.category?e(g.category)+' · ':''}${members(g).length}개 항목${g.archivedAt?' · 보관됨':''}</p>${g.description?`<p>${e(g.description)}</p>`:''}${g.type==='bucket'?`<div class="progress"><i style="width:${p.percent}%"></i></div><div class="progress-caption"><span>${p.done} / ${p.total} 완료</span><span>${p.percent}%</span></div>`:''}</div></button><button class="group-menu" data-action="groupMenu" data-id="${e(g.id)}" aria-label="${e(g.title)} 관리">${icon('more')}</button></article>`}
function section(title,body,link=''){return `<section class="section"><div class="section-heading"><h2>${title}</h2>${link?`<a href="#${link}">모두 보기 ${icon('arrow')}</a>`:''}</div>${body}</section>`}
function home(){const boards=activeGroups().filter(g=>g.type==='moodboard').slice(0,4);const buckets=activeGroups().filter(g=>g.type==='bucket'&&progress(g).percent<100).slice(0,3);const counts=new Map();activeItems().forEach(i=>i.tags.forEach(t=>counts.set(t,(counts.get(t)||0)+1)));const popular=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,12).map(([t])=>t);
const wishes=activeItems().filter(i=>i.type==='product'&&!i.purchased&&!i.archivedAt).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,4);
return `<div class="home-heading"><div class="eyebrow">COLLECT. ORGANIZE. REMEMBER.</div><h1>나의 취향 기록장</h1><p>좋아하는 것들로 채워가는 작은 서랍</p></div><div class="quick-actions">${button(icon('image')+' 이미지·링크 저장','addReference')}${button(icon('plus')+' 새 무드보드','addMoodboard')}${button(icon('collection')+' 새 취향 컬렉션','addCollection')}${button(icon('wish')+' 위시리스트 추가','addProduct')}${button(icon('bucket')+' 새 버킷리스트','addBucket')}</div><div class="home-layout"><div class="home-main">${section('나의 무드보드',boards.length?`<div class="group-grid">${boards.map(groupCard).join('')}</div>`:empty('나의 첫 무드보드','가을 룩북, 여행 레퍼런스, 좋아하는 색감. 주제별로 모아보세요.','addMoodboard','새 무드보드 만들기'),'moodboards')}</div><aside class="home-side">${section('진행 중인 버킷리스트',buckets.length?buckets.map(g=>{const p=progress(g);return `<a class="bucket-summary" style="display:block" href="#group:${e(g.id)}"><h3>${icon('bucket')} ${e(g.title)}</h3><div class="progress"><i style="width:${p.percent}%"></i></div><div class="progress-caption"><span>${p.done} / ${p.total} 완료</span><span>${p.percent}%</span></div></a>`}).join(''):empty('언젠가 해보고 싶은 일','작은 소망부터 기록해보세요.','addBucket','목록 만들기'),'buckets')}${section('지금의 위시리스트',wishes.length?`<div class="wish-preview">${wishes.map(i=>itemCard(i)).join('')}</div>`:'<p class="reading">갖고 싶은 물건을 담아두면 이곳에서 다시 만날 수 있어요.</p>','wishlists')}${section('최근 취향 키워드',popular.length?tagButtons(popular):'<p class="reading">기록에 태그를 붙여 나의 취향을 이어보세요.</p>')}</aside></div>`}

function libraryAll(){const values=activeItems().filter(i=>!i.archivedAt&&(libraryType==='all'||i.type===libraryType)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `<div class="page-heading"><div><h1>모든 기록</h1><p>서랍마다 흩어진 취향을 한눈에 모아보세요.</p></div></div><div class="toolbar"><div class="filters">${[['all','전체'],...Object.entries(ITEM_TYPES)].map(([v,t])=>`<button data-action="libraryType" data-value="${e(v)}" class="filter-chip ${libraryType===v?'active':''}">${e(t)}</button>`).join('')}</div></div><div class="masonry">${values.length?values.map(i=>itemCard(i)).join(''):empty('아직 담아둔 기록이 없어요','이미지와 취향, 물건과 소망을 하나씩 모아보세요.','addReference','기록 담기')}</div>`}
function sortedGroups(values){return [...values].sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'ko'):sort==='new'?b.createdAt.localeCompare(a.createdAt):a.order-b.order)}
function groupListing(type){const title=TYPES[type],values=sortedGroups(activeGroups().filter(g=>g.type===type));const intro={moodboard:'이미지로 모으는 나의 취향과 레퍼런스',collection:'좋아하는 대상과 오래 남기고 싶은 감상',wishlist:'사고 싶은 물건을, 나만의 속도로',bucket:'언젠가 꼭 해보고 싶은 일들을 기록해요'}[type];const addAction={moodboard:'addMoodboard',collection:'addCollection',wishlist:'addWishlist',bucket:'addBucket'}[type];let result=`<div class="page-heading"><div><div class="eyebrow">MY ${type.toUpperCase()}S</div><h1>${title}</h1><p>${intro}</p></div>${button(icon('plus')+' 새 '+title,addAction,'primary')}</div><div class="toolbar"><div class="filters">${button('내 '+title,'noop','filter-chip active')}${type==='collection'?button('전체 취향 보기','allTastes','filter-chip'):''}${type==='wishlist'?button('전체 상품 보기','allProducts','filter-chip'):''}${type==='bucket'?button('완료한 경험','completedGoals','filter-chip'):''}</div><div class="filters"><select id="groupSort" aria-label="목록 정렬"><option value="manual" ${sort==='manual'?'selected':''}>내가 정한 순</option><option value="new" ${sort==='new'?'selected':''}>최신순</option><option value="name" ${sort==='name'?'selected':''}>이름순</option></select><div class="view-switch"><button data-action="cards" class="${groupView==='cards'?'active':''}" aria-label="카드형 보기" aria-pressed="${groupView==='cards'}">${icon('grid')}</button><button data-action="list" class="${groupView==='list'?'active':''}" aria-label="목록형 보기" aria-pressed="${groupView==='list'}">${icon('list')}</button></div></div></div><div class="group-grid ${groupView==='list'?'list-view':''}">${values.map(groupCard).join('')}<button class="new-group-card" data-action="${addAction}">${icon('plus')}새 ${title}</button></div>`;
const standalone=activeItems().filter(i=>i.type===typeItem[type]&&!i.archivedAt&&!locations(i.id).some(g=>g.type===type));if(standalone.length)result+=section('아직 서랍에 담지 않은 항목',`<div class="masonry">${standalone.map(i=>itemCard(i)).join('')}</div>`);return result}
function filterItems(values){return values.filter(i=>(!category||i.category===category)&&(!tag||i.tags.some(t=>t.toLowerCase()===tag.toLowerCase()))&&(!favoriteOnly||i.favorite)&&(itemStatus==='all'||itemStatus==='open'&&!(i.done||i.purchased)||itemStatus==='done'&&(i.done||i.purchased)))}
function itemFilters(type,scopeCategory=''){return `<div class="toolbar"><div class="filters">${type==='taste'&&scopeCategory?`<span class="filter-chip active">${e(scopeCategory)}</span>`:type==='taste'?`<button data-action="category" data-value="" class="filter-chip ${!category?'active':''}">전체</button>${state().categories.map(c=>`<button data-action="category" data-value="${e(c)}" class="filter-chip ${category===c?'active':''}">${e(c)}</button>`).join('')}${button(icon('settings')+' 카테고리 관리','categories','filter-chip')}`:`<button data-action="itemStatus" data-value="all" class="filter-chip ${itemStatus==='all'?'active':''}">전체</button><button data-action="itemStatus" data-value="open" class="filter-chip ${itemStatus==='open'?'active':''}">${type==='product'?'구매 전':'진행 중'}</button><button data-action="itemStatus" data-value="done" class="filter-chip ${itemStatus==='done'?'active':''}">${type==='product'?'구매 완료':'완료'}</button>`}</div><button data-action="favoriteFilter" class="filter-chip ${favoriteOnly?'active':''}" aria-pressed="${favoriteOnly}">${icon('heart')} 즐겨찾기</button></div>`}
function allItems(type){const values=filterItems(activeItems().filter(i=>i.type===type&&!i.archivedAt));return `<div class="page-heading"><div><h1>${type==='taste'?'모든 취향':'모든 위시 상품'}</h1><p>분류와 상관없이 한곳에서 찾아보세요.</p></div>${button(icon('plus')+' '+(type==='taste'?'취향':'상품')+' 추가',type==='taste'?'addTaste':'addProduct','primary')}</div>${itemFilters(type)}<div class="masonry">${values.length?values.map(i=>itemCard(i)).join(''):empty('표시할 항목이 없어요','다른 분류를 선택하거나 새 기록을 담아보세요.',type==='taste'?'addTaste':'addProduct','새 기록 담기')}</div>`}
function paletteHtml(g){return g.palette?.length?`<div class="palette" aria-label="무드보드 대표 색상">${g.palette.map(c=>`<span title="${e(c)}" style="background:${color(c)}"></span>`).join('')}<small>${g.palette.map(e).join(' · ')}</small></div>`:''}
function groupDetail(g){const all=members(g).filter(i=>!i.archivedAt),values=filterItems(all),p=progress(g);const coverImage=g.coverId?`<img class="hero-cover" data-asset="${e(g.coverId)}" alt="${e(g.title)} 표지">`:'';const isBoard=g.type==='moodboard';let body;
if(isBoard&&canvasMode)body=collage(g);else if(g.type==='bucket')body=`${itemFilters('goal')}<div class="goal-list">${values.length?values.map(goalRow).join(''):empty('이 목록에 목표를 담아보세요','여러 목록에 연결한 목표의 완료 상태는 함께 바뀝니다.','addInGroup','새 목표 추가')}</div>`;else body=`${g.type==='collection'?itemFilters('taste',g.category||''):g.type==='wishlist'?itemFilters('product'):''}${isBoard?'<p class="board-order-hint">카드를 끌어 순서를 바꿀 수 있어요. 터치·키보드는 상세 보기의 앞/뒤 이동 버튼을 이용하세요.</p>':''}<div class="masonry" id="boardGrid">${values.length?values.map(i=>itemCard(i,{showLocation:false,showDate:!isBoard})).join(''):empty('이 서랍은 아직 비어 있어요','사진이나 텍스트를 담고 나만의 컬렉션을 시작해보세요.','addInGroup','새 항목 담기')}</div>`;
return `<a class="back-link" href="#${typeRoute[g.type]}">${icon('back')} ${TYPES[g.type]} 목록</a>${g.archivedAt?'<div class="notice">보관한 서랍입니다. 관리 메뉴에서 보관을 해제할 수 있어요.</div>':''}<div class="group-hero">${coverImage}<div class="hero-copy"><div class="eyebrow">${TYPES[g.type]}${g.type==='collection'&&g.category?' · '+e(g.category):''}</div><h1>${e(g.title)}</h1>${g.untitled?button('이름 붙이기','editGroup','small subtle',`data-id="${e(g.id)}"`):''}${g.description?`<p>${e(g.description)}</p>`:''}${g.startDate||g.endDate?`<small>${e(g.startDate||'시작일 미정')} — ${e(g.endDate||'종료일 미정')}</small>`:''}${g.type==='bucket'?`<div class="progress"><i style="width:${p.percent}%"></i></div><div class="progress-caption"><span>${p.done} / ${p.total}개 완료</span><span>${p.percent}%</span></div>`:''}${isBoard?paletteHtml(g):''}</div><div class="group-actions">${button(icon('edit')+' 편집','editGroup','',`data-id="${e(g.id)}"`)}${button(icon('more'),'groupMenu','',`data-id="${e(g.id)}" aria-label="서랍 관리"`)}</div></div><div class="toolbar"><div class="filters">${button(icon('plus')+' '+(g.type==='bucket'?'새 목표':g.type==='wishlist'?'상품':'항목')+' 추가','addInGroup','primary')}${button(icon('link')+' 기존 항목 연결','linkExisting')}${isBoard?button(icon('color')+' 팔레트','palette'):''}</div>${isBoard?`<div class="view-switch"><button data-action="gridMode" class="${!canvasMode?'active':''}" aria-pressed="${!canvasMode}">그리드</button><button data-action="canvasMode" class="${canvasMode?'active':''}" aria-pressed="${canvasMode}">콜라주</button></div>`:''}</div>${body}`}
function goalRow(i){const linked=locations(i.id).filter(g=>g.type==='bucket').length;const info=[i.done?'완료 · '+(i.completedAt||''):i.targetDate?'목표일 · '+i.targetDate:'',linked>1?'여러 목록에 연결됨':''].filter(Boolean).join(' · ');return `<article class="goal-row ${i.done?'completed':''}"><button class="goal-check ${i.done?'active':''}" data-action="toggleGoal" data-id="${e(i.id)}" aria-label="${e(i.title)} ${i.done?'완료 취소':'완료하기'}" aria-pressed="${!!i.done}">${i.done?icon('check'):''}</button><button class="goal-content" data-action="detail" data-id="${e(i.id)}"><strong class="${i.done?'done-title':''}">${e(i.title)}</strong>${info?`<small>${e(info)}</small>`:''}</button>${imgTag(i)}</article>`}

function archive(){const inRange=v=>(!from||v?.slice(0,10)>=from)&&(!to||v?.slice(0,10)<=to);const items=activeItems().filter(i=>(i.type==='goal'&&i.done||i.type==='product'&&i.purchased||i.archivedAt)&&inRange(i.type==='goal'&&i.done?i.completedAt:i.type==='product'&&i.purchased?i.purchasedAt:i.archivedAt)&&(archiveType==='all'||i.type===archiveType));const groups=state().groups.filter(g=>!g.deletedAt&&g.archivedAt&&inRange(g.archivedAt)&&(archiveType==='all'||g.type===archiveType));return `<div class="page-heading"><div><div class="eyebrow">MEMORIES TO KEEP</div><h1>아카이브</h1><p>지난 취향과, 이루어낸 경험을 돌아보는 곳</p></div>${button(icon('trash')+' 휴지통','trash')}</div><div class="toolbar"><div class="filters">${[['all','모두'],['goal','완료한 경험'],['product','구매한 물건'],['moodboard','보관한 무드보드'],['collection','보관한 컬렉션'],['taste','보관한 취향']].map(([v,t])=>`<button class="filter-chip ${archiveType===v?'active':''}" data-action="archiveType" data-value="${v}">${t}</button>`).join('')}</div><div class="filters"><label><small>시작일 </small><input id="archiveFrom" type="date" value="${e(from)}" aria-label="아카이브 시작일"></label><label><small>종료일 </small><input id="archiveTo" type="date" value="${e(to)}" aria-label="아카이브 종료일"></label></div></div>${groups.length?`<div class="group-grid">${groups.map(groupCard).join('')}</div>`:''}${items.length?`<div class="masonry" style="margin-top:24px">${items.map(i=>itemCard(i)).join('')}</div>`:''}${!items.length&&!groups.length?empty('아직 이곳에 남겨둔 기록이 없어요','완료한 목표, 구매한 물건, 보관한 취향은 삭제하지 않고 이곳에서 간직합니다.'):''}`}
function search(){const q=query.trim().toLowerCase(),matches=v=>!q||v.toLowerCase().includes(q);const items=activeItems().filter(i=>(!tag||i.tags.some(t=>t.toLowerCase()===tag.toLowerCase()))&&matches([i.title,i.note,i.review,i.category,i.brand,...i.tags].join(' ')));const groups=state().groups.filter(g=>!g.deletedAt&&!tag&&matches(g.title+' '+g.description));let body='';for(const [type,label]of Object.entries(TYPES)){const list=groups.filter(g=>g.type===type);if(list.length)body+=`<section class="results-section"><h2>${label} <small>${list.length}</small></h2>${list.map(g=>`<a class="result-group-link" href="#group:${e(g.id)}">${icon(typeIcon[g.type])} ${e(g.title)}<small>${members(g).length}개 항목</small></a>`).join('')}</section>`}for(const [type,label]of Object.entries(ITEM_TYPES)){const list=items.filter(i=>i.type===type);if(list.length)body+=`<section class="results-section"><h2>${label} <small>${list.length}</small></h2><div class="masonry">${list.map(i=>itemCard(i)).join('')}</div></section>`}return `<div class="page-heading"><div><h1>${tag?'#'+e(tag):'검색 결과'}</h1><p>${tag?'같은 키워드로 이어지는 나의 취향':query?'“'+e(query)+'”에 관한 기록':'서랍 전체에서 찾아보세요.'}</p></div></div>${body||empty('일치하는 기록이 없어요','다른 검색어나 태그로 다시 찾아보세요.')}`}
function trash(){const items=state().items.filter(i=>i.deletedAt),groups=state().groups.filter(g=>g.deletedAt);return `<div class="page-heading"><div><h1>휴지통</h1><p>삭제한 기록을 복원할 수 있어요. 아카이브와는 별개입니다.</p></div></div>${[...groups.map(g=>({...g,entity:'group'})),...items.map(i=>({...i,entity:'item'}))].map(v=>`<div class="trash-row"><div>${e(v.title)}<small>${v.entity==='group'?TYPES[v.type]:ITEM_TYPES[v.type]} · ${date(v.deletedAt)} 삭제</small></div>${button('복원','restore','',`data-id="${e(v.id)}" data-entity="${v.entity}"`)}</div>`).join('')||empty('휴지통이 비어 있어요','삭제한 기록이 생기면 이곳에서 복원할 수 있어요.')}`}
function render(){if(!state())return;const focused=root.contains(document.activeElement)?document.activeElement:null;const key=focused?.dataset.action?{action:focused.dataset.action,id:focused.dataset.id,value:focused.dataset.value,tag:focused.dataset.tag}:null;renderEpoch++;navRender();let html;if(route==='home')html=home();else if(routeType[route])html=groupListing(routeType[route]);else if(route.startsWith('group:')){const g=group(route.slice(6));html=g?groupDetail(g):empty('이 서랍을 찾을 수 없어요','삭제한 서랍은 휴지통에서 복원할 수 있어요.','trash','휴지통 열기')}else if(route==='all-items')html=libraryAll();else if(route==='all-tastes')html=allItems('taste');else if(route==='all-products')html=allItems('product');else if(route==='archive')html=archive();else if(route==='search')html=search();else if(route==='trash')html=trash();else html=home();root.dataset.route=route;root.innerHTML=(blocked?'<div class="status-banner">다른 탭에서 기록이 변경되었습니다. 작성 중인 내용을 확인하고 새로고침해주세요.</div>':'')+html;hydrate();bindView();if(key){const target=[...root.querySelectorAll('button[data-action],a[data-action]')].find(n=>n.dataset.action===key.action&&n.dataset.id===key.id&&n.dataset.value===key.value&&n.dataset.tag===key.tag);target?.focus({preventScroll:true})}}
function bindView(){const g=route.startsWith('group:')?group(route.slice(6)):null;if(g?.type==='moodboard'&&!canvasMode){const cards=root.querySelectorAll('#boardGrid .item-card');let dragged;cards.forEach(card=>{card.draggable=true;card.ondragstart=ev=>{dragged=card.dataset.id;ev.dataTransfer.setData('text/plain',dragged)};card.ondragover=ev=>{ev.preventDefault();card.classList.add('drop-target')};card.ondragleave=()=>card.classList.remove('drop-target');card.ondrop=async ev=>{ev.preventDefault();card.classList.remove('drop-target');if(dragged&&dragged!==card.dataset.id)try{await save(s=>{const target=s.groups.find(x=>x.id===g.id),position=target.memberIds.indexOf(card.dataset.id),arr=target.memberIds.filter(id=>id!==dragged);arr.splice(position,0,dragged);target.memberIds=arr;target.updatedAt=stamp()},[],'그리드 순서를 저장했어요.')}catch(err){notify(err.message)}}})}if(g&&canvasMode)bindCanvas(g);$('#groupSort')?.addEventListener('change',ev=>{sort=ev.target.value;render()});$('#archiveFrom')?.addEventListener('change',ev=>{from=ev.target.value;render()});$('#archiveTo')?.addEventListener('change',ev=>{to=ev.target.value;render()})}
let modalCleanup=()=>{},savingModal=false,activeFormSave=null,modalReturnFocus=null;
function showModal(title,body,{wide=false,footer=''}={}){if(!modal.open&&!modal.contains(document.activeElement))modalReturnFocus=document.activeElement;modalCleanup();modalCleanup=()=>{};if(modal.open)modal.close();modal.classList.toggle('wide',wide);modal.innerHTML=`<div class="modal-header"><h2 id="modalTitle" tabindex="-1">${e(title)}</h2><button class="icon-button" data-action="closeModal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="error-box" role="alert"></div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;modal.showModal();modal.scrollTop=0;hydrate(modal);return modal}
function formModal(title,body,onSubmit,{wide=false,saveLabel='저장하기'}={}){showModal(title,`<form id="editorForm">${body}</form>`,{wide,footer:`${button('취소','closeModal')}<button class="button primary" type="submit" form="editorForm" id="submitForm">${e(saveLabel)}</button>`});const f=$('#editorForm');f.dataset.accountEpoch=String(accountEpoch);f.onsubmit=async ev=>{ev.preventDefault();if(savingModal)return;if(Number(f.dataset.accountEpoch)!==accountEpoch){notify('계정이 바뀌었습니다. 다시 열어 저장해주세요.');return;}const saveButton=$('#submitForm'),error=modal.querySelector('.error-box');error.textContent='';const saveToken={};activeFormSave=saveToken;savingModal=true;saveButton.disabled=true;saveButton.textContent='저장 중…';try{const result=await onSubmit(f,new FormData(f));if(result!==false&&f.isConnected&&Number(f.dataset.accountEpoch)===accountEpoch)modal.close()}catch(err){if(!f.isConnected||Number(f.dataset.accountEpoch)!==accountEpoch)return;error.textContent=err.message||'저장하지 못했어요. 잠시 후 다시 시도해주세요.';error.scrollIntoView({block:'nearest'})}finally{if(activeFormSave===saveToken){savingModal=false;activeFormSave=null}if(saveButton.isConnected){saveButton.disabled=false;saveButton.textContent=saveLabel}}};return f}
let backdropPointer=false;
const outsideModal=ev=>{const r=modal.getBoundingClientRect();return ev.target===modal&&(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)};
modal.addEventListener('pointerdown',ev=>{backdropPointer=ev.isPrimary&&ev.button===0&&outsideModal(ev)});
modal.addEventListener('pointercancel',()=>{backdropPointer=false});
modal.addEventListener('click',ev=>{const dismiss=backdropPointer&&outsideModal(ev);backdropPointer=false;if(dismiss&&!savingModal)modal.close()});
modal.addEventListener('cancel',ev=>{if(savingModal)ev.preventDefault()});modal.addEventListener('close',()=>{if(modal.open)return;modalCleanup();modalCleanup=()=>{};if(modalReturnFocus?.isConnected&&!modalReturnFocus.closest('[inert]'))modalReturnFocus.focus({preventScroll:true});else if(state())root.focus({preventScroll:true})});
const groupEligible=(g,t)=>g.type==='moodboard'||g.type==='collection'&&(t==='taste'||t==='reference')||g.type==='wishlist'&&t==='product'||g.type==='bucket'&&t==='goal';
const acceptsItem=(g,i)=>groupEligible(g,i.type)&&(!g.category||g.type!=='collection'||i.type==='taste'&&i.category===g.category);
function setMembership(s,i,selected){for(const g of s.groups){if(g.deletedAt||g.archivedAt||!groupEligible(g,i.type))continue;const wanted=selected.includes(g.id);if(wanted&&!acceptsItem(g,i))throw Error('컬렉션의 카테고리와 항목의 분류를 맞춰주세요.');const had=g.memberIds.includes(i.id);if(wanted&&!had)g.memberIds.push(i.id);if(!wanted&&had)g.memberIds=g.memberIds.filter(id=>id!==i.id);if(wanted!==had)g.updatedAt=stamp()}}

function groupChecks(i,contextId,selectedIds=null){const values=activeGroups().filter(g=>acceptsItem(g,i));return `<div class="field-title">저장할 서랍 · 여러 곳을 선택할 수 있어요</div><div class="group-checks">${values.length?values.map(g=>checkbox('groupIds',TYPES[g.type]+' · '+g.title,(selectedIds?selectedIds.includes(g.id):g.memberIds.includes(i.id)||g.id===contextId)).replace('type="checkbox"',`type="checkbox" value="${e(g.id)}"`)).join(''):'<p class="help">아직 서랍이 없어요. 무드보드나 컬렉션을 만든 후 연결할 수 있어요.</p>'}</div>`}
function previewFile(f,name,previewId){let objectUrl;const file=f.elements[name];if(!file)return;file.addEventListener('change',()=>{if(!f.isConnected||Number(f.dataset.accountEpoch)!==accountEpoch)return;if(objectUrl)URL.revokeObjectURL(objectUrl);const target=$('#'+previewId);if(file.files[0]){objectUrl=URL.createObjectURL(file.files[0]);target.src=objectUrl;target.hidden=false;const remove={photo:'removeImage',cover:'removeCover',afterPhoto:'removeAfter'}[name];if(remove&&f.elements[remove])f.elements[remove].checked=false;if(name==='photo'&&f.elements.cardType&&(!f.elements.title.value.trim()||f.elements.title.value===f.dataset.autoImageTitle)){const title=file.files[0].name.replace(/\.[^.]+$/,'').slice(0,100)||'저장한 이미지';f.elements.title.value=title;f.dataset.autoImageTitle=title}}});const prior=modalCleanup;modalCleanup=()=>{prior();if(objectUrl)URL.revokeObjectURL(objectUrl)}}
async function readAsset(f,name,existing,assets,removeName){const file=f.elements[name]?.files[0];if(!file)return removeName&&f.elements[removeName]?.checked?null:existing||null;const {imageAsset}=await import('./data.js?v=small-dialogs-1');const asset=await imageAsset(file,{optimize:true});if(!f.isConnected||Number(f.dataset.accountEpoch)!==accountEpoch)throw Error('계정 또는 편집 화면이 바뀌어 저장을 중단했어요.');assets.push(asset);return asset.id}
function openGroupEditor(type,g=null){
const board=type==='moodboard',collection=type==='collection';
const nameField=input('title',board?'제목 (선택)':'제목',board&&g?.untitled?'':g?.title||'','text',`${board?'':'required '}maxlength="100" ${board?'placeholder="제목은 나중에 정해도 좋아요"':''}`);
const categoryField=collection?select('collectionCategory','컬렉션 카테고리',[['',g&&!g.category?'기존 컬렉션 · 분류 미지정':'카테고리를 선택해주세요'],...state().categories],g?.category||'').replace('<select name="collectionCategory">',`<select name="collectionCategory" ${!g||g.category?'required':''}>`):'';
const coverField=`${input('cover','대표 이미지','','file','accept="image/jpeg,image/png,image/webp,image/gif,image/avif"')}<img id="coverPreview" class="form-preview" ${g?.coverId?`data-asset="${e(g.coverId)}"`:'hidden'} alt="표지 미리보기">${g?.coverId?checkbox('removeCover','기존 표지 제거'):''}`;
const boardOptions=board?`<details class="form-more" ${g?.coverId||g?.palette?.length?'open':''}><summary>표지·색상·공개 범위 설정</summary>${coverField}${select('visibility','공개 범위',[['private','비공개 · 내 계정에만 보관']],'private')}<p class="help">로그인한 계정에 비공개로 저장합니다.</p>${input('palette','대표 색상 (쉼표로 구분)',g?.palette?.join(', ')||'','text','placeholder="#C89E9B, #725D50"')}</details>`:coverField;
const f=formModal(g?'서랍 편집':'새 '+TYPES[type],`${nameField}${board?'<p class="help compact-help">제목 없이 시작할 수 있어요. 나중에 이름을 붙여주세요.</p>':''}${categoryField}${collection?'<p class="help compact-help">선택한 카테고리의 항목만 이 컬렉션에 담습니다.</p>':''}${textarea('description','설명 (선택)',g?.description||'','maxlength="2000"')}${boardOptions}${type==='bucket'?`<div class="form-row">${input('startDate','시작일 (선택)',g?.startDate||'','date')}${input('endDate','종료일 (선택)',g?.endDate||'','date')}</div>`:''}`,async(f,fd)=>{
const typed=String(fd.get('title')||'').trim();if(!typed&&!board)throw Error('서랍 제목을 입력해주세요.');
const selectedCategory=String(fd.get('collectionCategory')||'');if(collection&&!selectedCategory&&(!g||g.category))throw Error('컬렉션의 카테고리를 선택해주세요.');
if(collection&&selectedCategory&&g){const incompatible=members(g).filter(i=>i.type!=='taste'||i.category!==selectedCategory);if(incompatible.length)throw Error(`다른 분류의 기록 ${incompatible.length}개가 연결되어 있어요. 기록의 분류를 먼저 맞추거나 새 컬렉션을 만들어주세요.`)}
if(type==='bucket'&&fd.get('startDate')&&fd.get('endDate')&&fd.get('startDate')>fd.get('endDate'))throw Error('종료일을 시작일 이후로 설정해주세요.');
const assets=[],coverId=await readAsset(f,'cover',g?.coverId,assets,'removeCover'),palette=String(fd.get('palette')||'').split(',').map(x=>x.trim()).filter(Boolean);if(palette.some(c=>!/^#[0-9a-f]{6}$/i.test(c)))throw Error('대표 색상은 #C89E9B 형식으로 입력해주세요.');let id=g?.id;
await save(s=>{const naming=board?moodboardName(s.groups,typed,g):{title:typed};const values={...naming,description:String(fd.get('description')||'').trim(),coverId,updatedAt:stamp(),visibility:'private'};if(collection)values.category=selectedCategory||null;if(type==='bucket'){values.startDate=fd.get('startDate');values.endDate=fd.get('endDate')}if(board)values.palette=palette.slice(0,12);if(g)Object.assign(s.groups.find(x=>x.id===g.id),values);else{const created=makeGroup(type,naming.title,values);s.groups.push(created);id=created.id}},assets);if(!g)go('group:'+id)
});previewFile(f,'cover','coverPreview');if(board&&!g&&matchMedia('(pointer:coarse)').matches)$('#modalTitle').focus({preventScroll:true});
}

function openItemEditor(type,i=null,contextId=null){const context=group(contextId||(route.startsWith('group:')?route.slice(6):''));const fixedCategory=type==='taste'&&context?.type==='collection'&&context.category?context.category:null;const base=i||makeItem(type,'',fixedCategory?{category:fixedCategory}:{});const photo=imgTag(base,'form-preview','id="itemPreview"')||'<img class="form-preview" id="itemPreview" alt="사진 미리보기" hidden>';const categoryOptions=fixedCategory?[fixedCategory]:[...new Set([...state().categories,...(base.category?[base.category]:[])])];const typeFields=type==='taste'?`<div class="form-row">${select('category','카테고리',categoryOptions,base.category||'기타')}${select('rating','개인 평점 (선택)',[['','평가하지 않음'],['1','★ · 1점'],['2','★★ · 2점'],['3','★★★ · 3점'],['4','★★★★ · 4점'],['5','★★★★★ · 5점']],String(base.rating||''))}</div>`:type==='product'?`<div class="form-row">${input('price','가격 · 원 (직접 입력)',base.price??'','number','min="0" max="999999999999" step="1"')}${select('priority','우선순위',[['low','낮음'],['normal','보통'],['high','높음']],base.priority||'normal')}</div>${input('brand','브랜드 또는 판매처',base.brand||'','text','maxlength="200"')}${checkbox('purchased','구매 완료',base.purchased)}${input('purchasedAt','구매 날짜 (선택)',base.purchasedAt||'','date')}<p class="help">가격은 직접 입력한 값입니다. 실시간 가격 추적은 하지 않습니다.</p>`:type==='goal'?`${checkbox('done','이 목표를 완료했어요',base.done)}`:`${select('cardType','카드 유형',[['image','이미지·링크'],['text','텍스트·메모'],['color','색상칩']],base.cardType||'image')}`;
const f=formModal(i&&state().items.some(x=>x.id===i.id)?'기록 수정':'새 '+ITEM_TYPES[type]+' 담기',`${input('title',type==='product'?'상품명':type==='goal'?'목표 제목':type==='reference'?'제목 (선택)':'제목',type==='reference'&&base.untitled?'':base.title,'text',`${type==='reference'?'':'required '}maxlength="100"`)}${typeFields}${fixedCategory?`<p class="help compact-help">이 컬렉션에서는 ‘${e(fixedCategory)}’ 분류로 저장합니다.</p>`:''}<div class="form-row image-fields">${input('photo','이미지 업로드','','file','accept="image/jpeg,image/png,image/webp,image/gif,image/avif"')}${input('imageUrl','또는 이미지 URL',base.imageUrl||'','url','placeholder="https://…"')}</div>${photo}${base.imageId||base.imageUrl?checkbox('removeImage','기존 이미지 제거'):''}${textarea('note',type==='taste'?'설명 또는 감상':'메모',base.note,'maxlength="5000"')}<div class="form-row">${input('tags','태그',base.tags.join(', '),'text','maxlength="600" placeholder="가을, 여행, 영감" list="tagSuggestions"')}<datalist id="tagSuggestions">${state().tags.map(t=>`<option value="${e(t)}"></option>`).join('')}</datalist>${input('sourceUrl',type==='product'?'상품 링크':'출처 또는 관련 링크',base.sourceUrl||'','url','placeholder="https://"')}</div><p class="help">웹페이지의 제목·이미지는 자동으로 가져오지 않습니다. 링크를 저장한 뒤 제목과 이미지를 직접 지정해주세요.</p>${input('color','텍스트·색상 카드 색상',color(base.color||'#F3EDE8'),'color')}<div id="itemDestinations">${groupChecks(base,contextId)}</div>${checkbox('favorite','즐겨찾기에 담기',base.favorite)}`,async(f,fd)=>{const enteredTitle=String(fd.get('title')||'').trim();if(!enteredTitle&&type!=='reference')throw Error('제목을 입력해주세요.');const note=String(fd.get('note')||'').trim(),file=f.elements.photo.files[0],cardType=String(fd.get('cardType')||'image');const fallback=file?.name.replace(/\.[^.]+$/,'')||note.split(/\r?\n/)[0]||(base.untitled?base.title:'')||(cardType==='text'?'제목 없는 메모':cardType==='color'?'색상칩':'제목 없는 이미지');const title=enteredTitle||fallback.slice(0,100);const source=String(fd.get('sourceUrl')||''),remote=String(fd.get('imageUrl')||'');if(source&&!safeUrl(source)||remote&&!safeUrl(remote))throw Error('http 또는 https 링크를 입력해주세요.');const assets=[];let imageId=await readAsset(f,'photo',base.imageId,assets,'removeImage');const freshPhoto=!!f.elements.photo.files[0],newRemote=!!remote&&remote!==String(base.imageUrl||'');if(newRemote&&!freshPhoto)imageId=null;const resolvedRemote=freshPhoto?'':fd.has('removeImage')&&!newRemote?'':safeUrl(remote);await save(s=>{let saved=s.items.find(x=>x.id===base.id);const values={title,...(type==='reference'?{untitled:!enteredTitle}:{}),note,tags:tags(fd.get('tags')),sourceUrl:safeUrl(source),imageId,imageUrl:resolvedRemote,color:fd.get('color'),favorite:fd.has('favorite'),updatedAt:stamp()};if(type==='taste'){values.category=fd.get('category');values.rating=fd.get('rating')?Number(fd.get('rating')):null}if(type==='reference')values.cardType=fd.get('cardType');if(type==='product'){values.price=fd.get('price')!==''?Number(fd.get('price')):'';values.brand=String(fd.get('brand')).trim();values.priority=fd.get('priority');values.purchased=fd.has('purchased');values.purchasedAt=values.purchased?(fd.get('purchasedAt')||base.purchasedAt||today()):null}if(type==='goal'){values.done=fd.has('done');values.completedAt=values.done?(base.completedAt||today()):null}if(saved)Object.assign(saved,values);else{s.items.push({...base,...values});saved=s.items.at(-1)}const selected=fd.getAll('groupIds');setMembership(s,saved,selected);const required=type==='goal'?'bucket':type==='product'?'wishlist':null;if(required&&!s.groups.some(g=>!g.deletedAt&&!g.archivedAt&&g.type===required&&g.memberIds.includes(saved.id))){let fallback=s.groups.find(g=>g.type===required&&!g.deletedAt&&!g.archivedAt);if(!fallback){fallback=makeGroup(required,required==='bucket'?'나의 버킷리스트':'나의 위시리스트');s.groups.push(fallback)}fallback.memberIds.push(saved.id)}},assets)});previewFile(f,'photo','itemPreview');if(type==='taste'&&!fixedCategory)f.elements.category.addEventListener('change',()=>{const selectedIds=[...f.querySelectorAll('[name=groupIds]:checked')].map(el=>el.value),candidate={...base,category:f.elements.category.value};$('#itemDestinations').innerHTML=groupChecks(candidate,contextId,selectedIds);if(locations(base.id).some(g=>g.type==='collection'&&g.category&&g.category!==candidate.category))$('#itemDestinations').insertAdjacentHTML('beforeend','<p class="help">다른 카테고리 컬렉션의 연결은 해제됩니다. 기록 자체는 유지됩니다.</p>')})}
function chooseNew(){showModal('무엇을 담아볼까요?',`<div class="menu-stack">${button(icon('image')+' 이미지·링크·텍스트','addReference')}${button(icon('collection')+' 좋아하는 취향','addTaste')}${button(icon('wish')+' 갖고 싶은 상품','addProduct')}${button(icon('bucket')+' 해보고 싶은 목표','addGoal')}${button(icon('board')+' 새로운 무드보드','addMoodboard')}${button(icon('folder')+' 새로운 컬렉션','addCollection')}</div>`)}
function showDetail(i){const current=route.startsWith('group:')?group(route.slice(6)):null;const image=imgTag(i)||`<div class="no-image"><h2>${e(i.title)}</h2>${i.cardType==='color'?`<div style="width:150px;height:100px;background:${color(i.color)}"></div>`:''}</div>`;const info=typeInfo(i);showModal('기록 들여다보기',`<div class="detail-layout"><div><div class="detail-image">${image}</div>${i.afterImageId?`<h3 style="margin-top:20px">완료 후의 장면</h3><div class="detail-image"><img data-asset="${e(i.afterImageId)}" alt="${e(i.title)} 완료 사진"></div>`:''}</div><div class="detail-copy"><div class="eyebrow">${ITEM_TYPES[i.type]}</div><h2>${e(i.title)}</h2>${i.note?`<p>${e(i.note)}</p>`:''}${info}${i.review?`<h3>경험 후 남긴 이야기</h3><p>${e(i.review)}</p>`:''}${tagButtons(i.tags)}${safeUrl(i.sourceUrl)?`<p><a href="${e(safeUrl(i.sourceUrl))}" target="_blank" rel="noopener noreferrer" class="text-button">출처·관련 링크 열기 ${icon('external')}</a></p>`:''}<div class="meta-line">${date(i.createdAt)} 저장${i.archivedAt?' · 보관됨':''}</div><div class="field-title">저장된 서랍</div><div class="location-list">${locations(i.id).map(g=>`<a href="#group:${e(g.id)}" data-action="location" data-id="${e(g.id)}">${e(g.title)}</a>`).join('')||'<small>아직 연결된 서랍이 없어요.</small>'}</div>${button(icon('link')+' 다른 서랍에도 담기','connectItem','',`data-id="${e(i.id)}"`)}${i.type==='goal'?`<div class="detail-controls">${button(icon('check')+(i.done?' 완료 취소':' 목표 완료하기'),'toggleGoalDetail','primary',`data-id="${e(i.id)}"`)}</div>`:''}${i.type==='product'?`<div class="detail-controls">${button(icon('check')+(i.purchased?' 구매 완료 취소':' 구매 완료로 기록'),'togglePurchase','primary',`data-id="${e(i.id)}"`)}</div>`:''}<div class="detail-controls">${button(icon('edit')+' 수정','editItem','',`data-id="${e(i.id)}"`)}${button(i.archivedAt?'보관 해제':'보관하기','archiveItem','',`data-id="${e(i.id)}"`)}${button(icon('trash'),'deleteItem','danger',`data-id="${e(i.id)}" aria-label="기록 삭제"`)}</div>${current?.type==='moodboard'?`<div class="detail-controls">${button('← 앞 순서로','itemEarlier','small',`data-id="${e(i.id)}"`)}${button('뒤 순서로 →','itemLater','small',`data-id="${e(i.id)}"`)}</div>`:''}</div></div>`,{wide:true})}
function typeInfo(i){if(i.type==='product')return `<p class="reading">${e(i.brand||'')}${i.price!==''&&i.price!=null?' · '+Number(i.price).toLocaleString('ko-KR')+'원':''}<br>우선순위: ${({high:'높음',normal:'보통',low:'낮음'})[i.priority]||'보통'}${i.purchased?'<br>구매 완료 · '+e(i.purchasedAt||'날짜 미정'):''}</p>`;if(i.type==='goal')return `<p class="reading">${i.targetDate?'목표일 · '+e(i.targetDate)+'<br>':''}${i.done?'완료일 · '+e(i.completedAt):'아직 이루어가는 중이에요.'}</p>`;if(i.type==='taste')return `<p class="reading">${e(i.category||'기타')}${i.rating?' · '+'★'.repeat(Math.min(5,i.rating)):''}</p>`;return ''}
function groupMenu(g){showModal(g.title,`<div class="menu-stack">${button(icon('edit')+' 이름·설명·표지 편집','editGroup','',`data-id="${e(g.id)}"`)}${button(icon('collection')+' 서랍 복제 (항목 함께 연결)','duplicateGroup','',`data-id="${e(g.id)}"`)}${button('↑ 앞 순서로 이동','groupEarlier','',`data-id="${e(g.id)}"`)}${button('↓ 뒤 순서로 이동','groupLater','',`data-id="${e(g.id)}"`)}${button(icon('archive')+(g.archivedAt?' 보관 해제':' 아카이브에 보관'),'archiveGroup','',`data-id="${e(g.id)}"`)}${button(icon('trash')+' 휴지통으로 이동','deleteGroup','danger',`data-id="${e(g.id)}"`)}</div><p class="help">서랍을 삭제해도 안의 기록은 삭제되지 않습니다. 복제한 서랍은 같은 항목을 참조하므로 목표 완료 상태도 공유됩니다.</p>`)}
function connectItem(i){const f=formModal('저장할 서랍 선택',groupChecks(i),async(f,fd)=>{const selected=fd.getAll('groupIds');await save(s=>{setMembership(s,i,selected);})},{});if(!f.querySelector('input'))f.insertAdjacentHTML('beforeend','<p class="help">먼저 새 서랍을 만든 후 다시 연결해주세요.</p>')}
function linkExisting(g){const candidates=activeItems().filter(i=>!g.memberIds.includes(i.id)&&acceptsItem(g,i));formModal('기존 기록 연결',`<p class="help">기록을 복사하지 않고 이 서랍에도 연결합니다. 완료 상태와 수정 내용은 함께 반영돼요.</p><div class="item-pick-list">${candidates.map(i=>checkbox('itemIds',i.title,false).replace('type="checkbox"',`type="checkbox" value="${e(i.id)}"`)).join('')||'<p class="reading">연결할 수 있는 다른 기록이 없어요.</p>'}</div>`,async(f,fd)=>{const ids=fd.getAll('itemIds');if(!ids.length)throw Error('연결할 기록을 선택해주세요.');await save(s=>{const target=s.groups.find(x=>x.id===g.id);target.memberIds=[...new Set([...target.memberIds,...ids])];target.updatedAt=stamp()})})}
function collage(g){if(!layoutDraft)layoutDraft=structuredClone(state().layouts[g.id]||{});const values=members(g).filter(i=>!i.archivedAt);values.forEach((i,index)=>{if(!layoutDraft[i.id])layoutDraft[i.id]={x:35+index%4*235,y:35+Math.floor(index/4)*290,w:215,h:260,z:index+1}});const selected=selectedTile&&layoutDraft[selectedTile]?layoutDraft[selectedTile]:null;return `<div class="notice">사진·메모·색상칩을 이동하거나 오른쪽 아래 모서리를 끌어 크기를 바꿔보세요. 키보드 방향키로 이동, Alt+방향키로 크기 변경이 가능해요. 모바일에서는 캔버스 빈 공간을 밀어 이동할 수 있어요.</div><div class="collage-tools">${button('배치 저장','saveLayout','primary')}${button('최근 저장 배치로 복원','restoreLayout')}${button('텍스트 카드 추가','addText')}${button('색상칩 추가','addColor')}<span class="layout-status" id="layoutStatus">${layoutDirty?'저장하지 않은 배치가 있어요.':state().layouts[g.id]?'저장된 배치':'기본 배치 · 편집 후 저장해주세요.'}</span></div><div class="collage-shell"><div class="collage-canvas" id="collageCanvas" style="height:${Math.max(850,...Object.values(layoutDraft).map(p=>p.y+p.h+40))}px">${values.map(i=>{const pos=layoutDraft[i.id];return `<div class="collage-tile ${selectedTile===i.id?'selected':''}" tabindex="0" role="button" aria-label="${e(i.title)} 배치 편집, 방향키로 이동" data-id="${e(i.id)}" style="left:${pos.x}px;top:${pos.y}px;width:${pos.w}px;height:${pos.h}px;z-index:${pos.z};${i.cardType==='color'?'background:'+color(i.color):''}">${imgTag(i)||`<div class="tile-text">${e(i.title)}${i.note?`<small>${e(i.note)}</small>`:''}</div>`}<span class="resize-handle" aria-hidden="true"></span></div>`}).join('')}</div></div><div class="collage-tools" id="positionControls">${['x','y','w','h'].map((key,index)=>`<label>${['가로 위치','세로 위치','너비','높이'][index]}<input id="pos-${key}" type="number" min="${key==='w'?60:key==='h'?50:0}" max="${key==='x'||key==='w'?1000:5000}" value="${selected?.[key]??''}" ${selected?'':'disabled'}></label>`).join('')}${button('맨 앞으로','bringForward','',selected?'':'disabled')}${button('선택 항목 상세','selectedDetail','',selected?'':'disabled')}</div>${!values.length?'<p class="reading">항목을 추가하면 이 캔버스에 배치할 수 있어요.</p>':''}`}
function layoutChanged(){layoutDirty=true;$('#layoutStatus').textContent='저장하지 않은 배치가 있어요.'}
function bindCanvas(g){function selectTile(tile){selectedTile=tile.dataset.id;root.querySelectorAll('.collage-tile').forEach(t=>t.classList.toggle('selected',t===tile));for(const key of ['x','y','w','h']){const field=$('#pos-'+key);field.disabled=false;field.value=Math.round(layoutDraft[selectedTile][key])}root.querySelectorAll('[data-action=bringForward],[data-action=selectedDetail]').forEach(b=>b.disabled=false)}
function update(tile){const p=layoutDraft[tile.dataset.id];tile.style.left=p.x+'px';tile.style.top=p.y+'px';tile.style.width=p.w+'px';tile.style.height=p.h+'px';tile.style.zIndex=p.z;$('#collageCanvas').style.height=Math.max(850,...Object.values(layoutDraft).map(p=>p.y+p.h+40))+'px';selectTile(tile);layoutChanged()}
root.querySelectorAll('.collage-tile').forEach(tile=>{tile.addEventListener('pointerdown',ev=>{if(ev.button!==0)return;selectTile(tile);tile.focus({preventScroll:true});const resize=ev.target.classList.contains('resize-handle'),start={x:ev.clientX,y:ev.clientY,...layoutDraft[tile.dataset.id]};start.pointerX=ev.clientX;start.pointerY=ev.clientY;tile.setPointerCapture(ev.pointerId);const move=event=>{const p=layoutDraft[tile.dataset.id],dx=event.clientX-start.pointerX,dy=event.clientY-start.pointerY;if(resize){p.w=Math.min(1000-p.x,Math.max(60,start.w+dx));p.h=Math.min(4800-p.y,Math.max(50,start.h+dy))}else{p.x=Math.max(0,Math.min(1000-p.w,start.x+dx));p.y=Math.max(0,Math.min(4500,start.y+dy))}update(tile)};const finish=()=>{tile.removeEventListener('pointermove',move);tile.removeEventListener('pointerup',finish);tile.removeEventListener('pointercancel',finish)};tile.addEventListener('pointermove',move);tile.addEventListener('pointerup',finish);tile.addEventListener('pointercancel',finish)});tile.addEventListener('focus',()=>selectTile(tile));tile.addEventListener('keydown',ev=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();const p=layoutDraft[tile.dataset.id],step=ev.shiftKey?10:1,axis=ev.key==='ArrowLeft'||ev.key==='ArrowRight'?'x':'y',delta=ev.key==='ArrowLeft'||ev.key==='ArrowUp'?-step:step;if(ev.altKey){const dim=axis==='x'?'w':'h';p[dim]=Math.max(dim==='w'?60:50,Math.min(dim==='w'?1000-p.x:4800-p.y,p[dim]+delta))}else p[axis]=Math.max(0,Math.min(axis==='x'?1000-p.w:4500,p[axis]+delta));update(tile)});tile.addEventListener('dblclick',()=>showDetail(item(tile.dataset.id)))});
for(const key of ['x','y','w','h'])$('#pos-'+key)?.addEventListener('change',ev=>{if(!selectedTile)return;const p=layoutDraft[selectedTile];p[key]=Math.round(Number(ev.target.value)||0);p.w=Math.min(1000,Math.max(60,p.w));p.h=Math.min(4800,Math.max(50,p.h));p.x=Math.max(0,Math.min(1000-p.w,p.x));p.y=Math.max(0,Math.min(4800-p.h,p.y));const tile=[...root.querySelectorAll('.collage-tile')].find(t=>t.dataset.id===selectedTile);update(tile)})}
async function extractPalette(blob){const bitmap=await createImageBitmap(blob);const c=document.createElement('canvas');c.width=72;c.height=72;c.getContext('2d').drawImage(bitmap,0,0,72,72);bitmap.close();const pixels=c.getContext('2d').getImageData(0,0,72,72).data,bins=new Map();for(let n=0;n<pixels.length;n+=4){if(pixels[n+3]<180)continue;const rgb=[pixels[n],pixels[n+1],pixels[n+2]].map(v=>Math.min(255,Math.round(v/32)*32)),key=rgb.join(',');bins.set(key,(bins.get(key)||0)+1)}const chosen=[];for(const [key]of [...bins].sort((a,b)=>b[1]-a[1])){const rgb=key.split(',').map(Number);if(chosen.every(prev=>Math.hypot(...rgb.map((n,i)=>n-prev[i]))>55))chosen.push(rgb);if(chosen.length===6)break}return chosen.map(rgb=>'#'+rgb.map(n=>n.toString(16).padStart(2,'0')).join(''))}
function paletteEditor(g){const f=formModal('무드보드의 색감',`${input('palette','대표 색상 (최대 12개)',g.palette?.join(', ')||'','text','placeholder="#C89E9B, #725D50"')}<div id="palettePreview" class="palette">${(g.palette||[]).map(c=>`<span style="background:${color(c)}"></span>`).join('')}</div><div class="form-row">${input('pickColor','직접 색 고르기','#C89E9B','color')}<div style="align-self:end;margin-bottom:17px">${button('색상 추가','appendPaletteColor')}</div></div>${input('extractFile','이미지에서 색 추출','','file','accept="image/jpeg,image/png,image/webp,image/gif,image/avif"')}${button('선택한 이미지에서 추출','extractPalette')}<p class="help">기기에서 선택한 이미지의 대표 색상을 추출합니다. 외부 이미지의 접근 제한을 우회하지 않습니다.</p>`,async(f,fd)=>{const values=String(fd.get('palette')).split(',').map(v=>v.trim()).filter(Boolean);if(values.some(v=>!/^#[0-9a-f]{6}$/i.test(v)))throw Error('색상은 #C89E9B 형식으로 입력해주세요.');await save(s=>{s.groups.find(x=>x.id===g.id).palette=[...new Set(values)].slice(0,12)})});f.elements.palette.oninput=()=>{$('#palettePreview').innerHTML=f.elements.palette.value.split(',').map(c=>`<span style="background:${color(c.trim())}"></span>`).join('')}}
function categoriesDialog(){showModal('카테고리 관리',`<p class="help">이름을 바꾸면 해당 취향의 카테고리도 함께 바뀝니다. 삭제한 카테고리의 기록은 ‘기타’로 옮기며, 기록 자체는 지우지 않습니다.</p><div id="categoryRows">${state().categories.map((c,index)=>`<div class="category-row"><input value="${e(c)}" aria-label="${e(c)} 카테고리 이름" data-index="${index}">${button('변경','renameCategory','small',`data-index="${index}"`)}${c!=='기타'?button(icon('trash'),'deleteCategory','small',`data-index="${index}" aria-label="${e(c)} 카테고리 삭제"`):''}</div>`).join('')}</div><form id="categoryForm"><label class="field" style="margin-top:20px">새 카테고리<input name="title" required maxlength="50" placeholder="나만의 분류"></label><button class="button primary">카테고리 추가</button></form>`);$('#categoryForm').onsubmit=async ev=>{ev.preventDefault();const value=ev.target.elements.title.value.trim();try{if(!value||state().categories.includes(value))throw Error('겹치지 않는 카테고리 이름을 입력해주세요.');await save(s=>s.categories.push(value));categoriesDialog()}catch(err){notify(err.message)}}}
function updateInstallHint(){const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone;return installed?'홈 화면 앱으로 사용 중이에요.':installPrompt?'설치하면 홈 화면에서 바로 열 수 있어요.':/iPhone|iPad|iPod/.test(navigator.userAgent)?'Safari 공유 버튼 → 홈 화면에 추가를 선택해주세요.':'브라우저 메뉴 → 앱 설치 또는 홈 화면에 추가를 선택해주세요.'}
function settings(){const settingsOwner=store;showModal('나의 서랍 설정',`<section class="settings-section"><h3>하루결 계정으로 연결됨</h3><p>${e(cloud?.user?.email||'')}<br><span id="accountStatusText">${e(cloud?.message||'계정 저장 확인 중')}</span></p><div class="detail-controls">${button('지금 계정에 저장','syncNow')}${button('저장 충돌 확인','showConflict')}${button('로그아웃','logout')}</div><p class="help">이미지와 기록을 계정별로 저장합니다. 오프라인이나 서버 오류 시 기기 기록을 유지하며, 서버에 저장되었는지는 상태 표시에서 확인할 수 있어요.</p>${button(icon('download')+' 전체 백업 다운로드','export','primary')} ${button(icon('upload')+' 백업 불러오기','import')}<input id="backupFile" type="file" accept="application/json" hidden><p class="help">기기를 바꾸거나 사이트 데이터를 지우기 전에 백업해주세요. 백업에는 이미지와 콜라주 배치도 포함됩니다.</p>${state().migration?.legacyPresent?button('전환 전 원본 기록 다운로드','exportOriginal','small'):''}</section><section class="settings-section"><h3>홈 화면에서 사용하기</h3><p id="installGuide">${updateInstallHint()}</p>${button('앱 설치 안내','install')}</section><section class="settings-section"><h3>서랍 정리</h3>${button('취향 카테고리 관리','categories')} ${button('휴지통 열기','trash')}<p class="help">휴지통과 아카이브는 별개입니다. 삭제한 항목은 휴지통에서 복원할 수 있습니다.</p></section><section class="settings-section"><h3>데이터 전환 및 안전 백업</h3><p>기존 원본은 지우지 않습니다. 기기 기록을 로그인 계정으로 가져올 수 있으며, 다른 계정의 보관함은 열지 않습니다.</p>${button('이 기기의 기존 기록 연결','offerLegacy','small')} ${button('동기화 전 안전 백업 보기','safetyBackups','small')} ${button('서버의 이전 저장 보기','serverBackups','small')}</section><small>arnit. · PERSONAL ARCHIVE 3.0</small>`);$('#backupFile').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>150*1024*1024)throw Error('150MB 이하의 백업 파일을 선택해주세요.');const parsed=JSON.parse(await file.text());if(settingsOwner!==store||!modal.open)throw Error('계정이 바뀌어 불러오기를 취소했어요.');if(!confirm('백업을 현재 기록과 합칩니다. 같은 ID의 항목은 백업의 내용으로 바뀝니다. 계속할까요?'))return;await settingsOwner.import(parsed);if(settingsOwner!==store)return;render();cloud?.changed();notify('이미지와 연결 정보를 포함해 백업을 불러왔어요.');modal.close()}catch(err){modal.querySelector('.error-box').textContent=err.message||'백업 파일을 읽지 못했어요.'}finally{ev.target.value=''}}}
async function action(name,el){const id=el?.dataset.id,value=el?.dataset.value,g=route.startsWith('group:')?group(route.slice(6)):null,i=id?item(id):null;switch(name){
case 'noop':break;case 'closeModal':if(!savingModal)modal.close();break;
case 'addReference':openItemEditor('reference',null,g?.id);break;case 'addTaste':openItemEditor('taste',null,g?.type==='collection'?g.id:null);break;case 'addProduct':openItemEditor('product',null,g?.id);break;case 'addGoal':openItemEditor('goal',null,g?.id);break;
case 'addMoodboard':openGroupEditor('moodboard');break;case 'addCollection':openGroupEditor('collection');break;case 'addWishlist':openGroupEditor('wishlist');break;case 'addBucket':openGroupEditor('bucket');break;
case 'addInGroup':if(g)openItemEditor(typeItem[g.type],null,g.id);break;
case 'addText':case 'addColor':if(g){const draft=makeItem('reference','',{cardType:name==='addText'?'text':'color',color:name==='addColor'?'#C89E9B':'#F3EDE8'});openItemEditor('reference',draft,g.id)}break;
case 'group':go('group:'+id);break;case 'location':modal.close();go('group:'+id);break;
case 'detail':if(i)showDetail(i);break;case 'editItem':if(i)openItemEditor(i.type,i);break;
case 'favorite':if(i)await save(s=>{const target=s.items.find(x=>x.id===id);target.favorite=!target.favorite;target.updatedAt=stamp()},[],'즐겨찾기를 변경했어요.');break;
case 'editGroup':{const target=group(id);if(target)openGroupEditor(target.type,target);break}case 'groupMenu':{const target=group(id);if(target)groupMenu(target);break}
case 'duplicateGroup':{const old=group(id);if(old){const copy=makeGroup(old.type,old.title+' 복사본',{...structuredClone(old),id:uid(),title:old.title+' 복사본',createdAt:stamp(),updatedAt:stamp(),order:Date.now(),deletedAt:null,archivedAt:null});await save(s=>{s.groups.push(copy);if(s.layouts[old.id])s.layouts[copy.id]=structuredClone(s.layouts[old.id])},[],'같은 항목을 연결한 서랍을 복제했어요.');modal.close();go('group:'+copy.id)}break}
case 'archiveGroup':{const target=group(id);if(target){await save(s=>{s.groups.find(x=>x.id===id).archivedAt=target.archivedAt?null:stamp()});modal.close()}break}
case 'deleteGroup':if(group(id)&&confirm('이 서랍을 휴지통으로 옮길까요? 안의 기록은 삭제하지 않습니다.')){await save(s=>{s.groups.find(x=>x.id===id).deletedAt=stamp()});modal.close();go('trash')}break;
case 'groupEarlier':case 'groupLater':{const target=group(id);if(target){const values=activeGroups().filter(x=>x.type===target.type).sort((a,b)=>a.order-b.order),index=values.findIndex(x=>x.id===id),next=index+(name==='groupEarlier'?-1:1);if(next<0||next>=values.length){notify('더 이동할 수 없어요.');break}await save(s=>{const ids=values.map(x=>x.id);[ids[index],ids[next]]=[ids[next],ids[index]];ids.forEach((key,idx)=>s.groups.find(x=>x.id===key).order=idx)},[],'서랍 순서를 저장했어요.');sort='manual';render();modal.close()}break}
case 'itemEarlier':case 'itemLater':if(g){const index=g.memberIds.indexOf(id),next=index+(name==='itemEarlier'?-1:1);if(next<0||next>=g.memberIds.length){notify('더 이동할 수 없어요.');break}await save(s=>{const arr=s.groups.find(x=>x.id===g.id).memberIds;[arr[index],arr[next]]=[arr[next],arr[index]]},[],'그리드 순서를 변경했어요.');showDetail(item(id))}break;
case 'connectItem':if(i)connectItem(i);break;case 'linkExisting':if(g)linkExisting(g);break;
case 'deleteItem':if(i&&confirm('이 기록을 휴지통으로 옮길까요? 모든 연결된 서랍에서 숨겨집니다.')){await save(s=>{s.items.find(x=>x.id===id).deletedAt=stamp()});modal.close()}break;
case 'archiveItem':if(i){await save(s=>{s.items.find(x=>x.id===id).archivedAt=i.archivedAt?null:stamp()});modal.close()}break;
case 'restore':await save(s=>{const values=el.dataset.entity==='group'?s.groups:s.items;const target=values.find(x=>x.id===id);if(target)target.deletedAt=null},[],'원래 기록을 복원했어요.');break;
case 'toggleGoal':case 'toggleGoalDetail':if(i){await save(s=>{const target=s.items.find(x=>x.id===id);target.done=!target.done;target.completedAt=target.done?today():null;target.updatedAt=stamp()},[],'연결된 모든 버킷리스트에 완료 상태를 반영했어요.');if(name==='toggleGoalDetail')showDetail(item(id))}break;
case 'togglePurchase':if(i){await save(s=>{const target=s.items.find(x=>x.id===id);target.purchased=!target.purchased;target.purchasedAt=target.purchased?today():null;target.updatedAt=stamp()},[],'구매 기록을 변경했어요.');showDetail(item(id))}break;
case 'cards':groupView='cards';render();break;case 'list':groupView='list';render();break;
case 'allTastes':go('all-tastes');break;case 'allProducts':go('all-products');break;case 'completedGoals':go('archive');archiveType='goal';render();break;
case 'libraryType':libraryType=value||'all';render();break;case 'category':category=value||'';render();break;case 'favoriteFilter':favoriteOnly=!favoriteOnly;render();break;case 'itemStatus':itemStatus=value;render();break;case 'archiveType':archiveType=value;render();break;
case 'tag':if(canLeave()){layoutDirty=false;layoutDraft=null;query='';tag=el.dataset.tag;$('#globalSearch').value='';route='search';history.pushState(null,'','#search');modal.close();render();window.scrollTo({top:0})}break;
case 'gridMode':if(canLeave()){canvasMode=false;layoutDirty=false;layoutDraft=null;render()}break;case 'canvasMode':canvasMode=true;render();break;
case 'saveLayout':if(g){const next=structuredClone(layoutDraft);await save(s=>{s.layouts[g.id]=next},[],'콜라주 배치를 저장했어요.');layoutDirty=false;render()}break;
case 'restoreLayout':if(g&&canLeave()){layoutDraft=structuredClone(state().layouts[g.id]||{});layoutDirty=false;render()}break;
case 'bringForward':if(selectedTile&&layoutDraft){layoutDraft[selectedTile].z=Math.max(...Object.values(layoutDraft).map(p=>p.z))+1;layoutDirty=true;render()}break;
case 'selectedDetail':if(selectedTile&&item(selectedTile))showDetail(item(selectedTile));break;
case 'palette':if(g)paletteEditor(g);break;
case 'appendPaletteColor':{const f=$('#editorForm'),v=f.elements.pickColor.value,values=f.elements.palette.value.split(',').map(x=>x.trim()).filter(Boolean);values.push(v);f.elements.palette.value=[...new Set(values)].slice(0,12).join(', ');f.elements.palette.dispatchEvent(new Event('input'));break}
case 'extractPalette':{const f=$('#editorForm'),file=f.elements.extractFile.files[0];if(!file)throw Error('색을 추출할 이미지를 먼저 선택해주세요.');if(file.size>20*1024*1024)throw Error('20MB 이하 이미지를 선택해주세요.');el.disabled=true;try{const colors=await extractPalette(file);f.elements.palette.value=colors.join(', ');f.elements.palette.dispatchEvent(new Event('input'));notify('이미지에서 대표 색상을 추출했어요.')}finally{el.disabled=false}break}
case 'categories':categoriesDialog();break;
case 'renameCategory':{const index=Number(el.dataset.index),field=modal.querySelector(`input[data-index="${index}"]`),old=state().categories[index],name=field.value.trim();if(!name||name!==old&&state().categories.includes(name))throw Error('겹치지 않는 카테고리 이름을 입력해주세요.');if(old==='기타'&&name!=='기타')throw Error('기본 카테고리 ‘기타’는 유지합니다.');await save(s=>{s.categories[index]=name;s.items.filter(i=>i.category===old).forEach(i=>i.category=name);s.groups.filter(g=>g.type==='collection'&&g.category===old).forEach(g=>g.category=name)});categoriesDialog();break}
case 'deleteCategory':{const old=state().categories[Number(el.dataset.index)];if(old==='기타')break;if(confirm('이 분류의 기록은 ‘기타’로 옮깁니다. 카테고리를 삭제할까요?')){await save(s=>{s.categories=s.categories.filter(c=>c!==old);s.items.filter(i=>i.category===old).forEach(i=>i.category='기타');s.groups.filter(g=>g.type==='collection'&&g.category===old).forEach(g=>g.category='기타')});categoriesDialog()}break}
case 'settings':settings();break;case 'trash':modal.close();go('trash');break;
case 'export':el.disabled=true;try{download(await store.export(),'취향서랍-전체-'+today()+'.json');notify('이미지를 포함한 전체 백업을 다운로드했어요.')}finally{el.disabled=false}break;
case 'import':$('#backupFile').click();break;
case 'exportOriginal':{const original=await store.original();if(original)download(original.raw,'취향서랍-전환전-원본.json');else notify('보관된 이전 원본이 없어요.');break}
case 'offerLegacy':await offerLegacy();break;case 'syncNow':await cloud.sync();break;case 'showConflict':showConflict();break;case 'logout':if(confirm('로그아웃할까요? 같은 브라우저의 하루결 로그인에도 반영됩니다. 아직 계정에 저장되지 않은 기록은 이 계정의 기기 보관함에 유지됩니다.'))await cloud.logout();break;case 'adoptLegacy':await adoptLegacy();break;case 'skipLegacy':modal.close();break;case 'useCloudRemote':if(confirm('현재 기기 기록을 안전 백업한 뒤 서버 기록으로 바꿀까요?')){await cloud.resolve('remote');modal.close()}break;case 'useCloudLocal':if(confirm('양쪽 기록을 안전하게 보관한 뒤 이 기기 기록을 계정에 저장할까요?')){await cloud.resolve('local');modal.close()}break;case 'serverBackups':{const meta=await store.meta(cloud.databaseId),rows=[];for(let rev=meta.revision-1;rev>=Math.max(1,meta.revision-10);rev--)rows.push(`<div class="trash-row"><div>계정 저장 버전 ${rev}</div>${button('백업 다운로드','serverBackup','small',`data-id="${rev}"`)}</div>`);showModal('서버의 이전 저장',rows.join('')||'<p class="reading">아직 이전 저장 버전이 없어요.</p>');break}case 'serverBackup':{el.disabled=true;try{download(await cloud.downloadBackup(Number(id)),'아르닛-계정-이전버전-'+id+'.json');notify('서버의 이전 기록과 이미지를 백업했어요.')}finally{el.disabled=false}break}case 'safetyBackups':await safetyBackups();break;case 'downloadSafety':{const rows=await store.safetyBackups(),row=rows.find(x=>x.id===id);if(row?.library){const snapshot=await store.export();snapshot.library=row.library;download(snapshot,'아르닛-안전백업-'+today()+'.json')}break;}
case 'install':if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else notify(updateInstallHint());break;
}}
document.addEventListener('click',ev=>{const target=ev.target.closest('[data-action]');if(!target)return;if(target.tagName==='A')ev.preventDefault();action(target.dataset.action,target).catch(err=>{const error=modal.open?modal.querySelector('.error-box'):null;if(error)error.textContent=err.message;else notify(err.message||'작업을 완료하지 못했어요.')})});
$('#newItem').onclick=()=>{const g=route.startsWith('group:')?group(route.slice(6)):null;if(g)openItemEditor(typeItem[g.type],null,g.id);else chooseNew()};$('#addFolder').onclick=()=>openGroupEditor('collection');$('#sidebarSettings').onclick=settings;$('#userMenu').onclick=settings;$('#searchIcon').innerHTML=icon('search');$('#menuToggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebarBackdrop').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open));$('.app').inert=open;$('#mobileNav').inert=open;if(open)$('#navigation a').focus()};$('#sidebarBackdrop').onclick=closeSidebar;window.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!modal.open)closeSidebar();if(ev.key==='Tab'&&$('#sidebar').classList.contains('open')&&!modal.open){const nodes=[...$('#sidebar').querySelectorAll('a,button')],first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});$('#searchForm').onsubmit=ev=>{ev.preventDefault();if(!canLeave())return;layoutDirty=false;layoutDraft=null;tag='';query=$('#globalSearch').value.trim();route='search';history.pushState(null,'','#search');render();closeSidebar()};
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev});window.addEventListener('appinstalled',()=>{installPrompt=null;notify('아르닛이 홈 화면에 추가되었어요.')});
store.onExternal=async()=>{if(modal.open||layoutDirty){blocked=true;notify('다른 탭에서 기록이 바뀌었어요. 작성 내용을 확인하고 새로고침해주세요.');return}try{await store.reload();blocked=false;render();cloud?.changed()}catch(err){notify(err.message)}};window.addEventListener('storage',ev=>{if(ev.key===LEGACY_KEY){notify('이전 버전의 기록이 바뀌었어요. 설정에서 이전 기록을 가져올 수 있습니다.')}});
function showOpenError(err){root.innerHTML=`<section class="error-page"><h1>기록을 안전하게 열지 못했어요</h1><p>${e(err.message)}<br>기존 데이터를 초기화하거나 덮어쓰지 않았습니다.</p><button id="rescueLegacy" class="button primary">이전 기록 원본 다운로드</button> <button id="retryOpen" class="button">다시 열기</button></section>`;$('#rescueLegacy').onclick=()=>{try{const raw=localStorage.getItem(LEGACY_KEY);if(raw)download(raw,'취향서랍-원본복구.json');else notify('이전 원본을 찾지 못했어요. 사이트 데이터를 삭제하지 마세요.')}catch{notify('원본을 읽지 못했어요.')}};$('#retryOpen').onclick=()=>location.reload()}
function authGate(message=''){let gate=$('#authGate');if(!gate){gate=document.createElement('section');gate.id='authGate';document.body.append(gate)}gate.hidden=false;gate.innerHTML=`<div class="auth-card"><div class="auth-brand">arnit.</div><p class="auth-subtitle">나를 이루는 작은 조각들</p><h1>나의 아르닛으로 들어가기</h1><p class="reading">하루결에서 쓰는 이메일 계정으로 로그인하세요.<br>사진과 취향, 소망을 계정별로 보관합니다.</p><form id="authForm">${input('email','이메일','','email','required autocomplete="username"')}${input('password','비밀번호','','password','required minlength="6" autocomplete="current-password"')}<button class="button primary" type="submit">로그인</button><button class="button" id="signupButton" type="button">처음이라면 회원가입</button><p id="authStatus" role="status">${e(message||'이메일 인증을 완료한 계정으로 이용할 수 있어요.')}</p></form><small>기존 기기 기록은 지우지 않으며, 로그인 후 연결할 수 있어요.</small>${!cloud?.auth&&cloud?.phase==='error'?'<button id="retryAuth" class="button" type="button">로그인 연결 다시 시도</button>':''}</div>`;gate.querySelectorAll('#authForm button').forEach(b=>b.disabled=!cloud?.auth);$('#retryAuth')?.addEventListener('click',()=>location.reload());$('#authForm').onsubmit=async ev=>{ev.preventDefault();const f=ev.target,buttons=f.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);$('#authStatus').textContent='로그인하고 있어요…';try{await cloud.login(f.elements.email.value.trim(),f.elements.password.value)}catch(err){$('#authStatus').textContent=cloud.friendly(err)}finally{buttons.forEach(b=>b.disabled=false)}};$('#signupButton').onclick=async()=>{const f=$('#authForm');if(!f.reportValidity())return;f.querySelectorAll('button').forEach(b=>b.disabled=true);try{$('#authStatus').textContent=await cloud.signup(f.elements.email.value.trim(),f.elements.password.value)}catch(err){$('#authStatus').textContent=cloud.friendly(err)}finally{f.querySelectorAll('button').forEach(b=>b.disabled=false)}}}
function lockApp(locked){$('.app').inert=locked;$('#sidebar').inert=locked;$('#mobileNav').inert=locked;document.body.classList.toggle('signed-out',locked)}
async function accountReady(user,message){const epoch=++accountEpoch;lockApp(true);root.innerHTML='';$('#folders').innerHTML='';legacyOffer?.store?.close();legacyOffer=null;blocked=false;layoutDirty=false;layoutDraft=null;modal.close();savingModal=false;activeFormSave=null;const previous=store,target=new LibraryStore({owner:user?.uid||null});store=target;await previous.close();if(epoch!==accountEpoch||target!==store){target.close();return}lockApp(!user);if(!user){root.innerHTML='';authGate(message);return}$('#authGate')?.setAttribute('hidden','');lockApp(false);root.innerHTML='<div class="loading">나의 계정 보관함을 열고 있어요…</div>';try{await target.open();if(target!==store||epoch!==accountEpoch)return;target.onExternal=async()=>{if(target!==store)return;if(modal.open||layoutDirty){blocked=true;notify('다른 탭의 기록이 변경됐어요. 작성 내용을 확인하고 새로고침해주세요.');return}await target.reload();render();cloud.changed()};route=decodeURIComponent(location.hash.slice(1))||'home';render();await cloud.connect(target);if(target!==store)return;if(cloud.phase!=='conflict')await offerLegacy(true)}catch(err){showOpenError(err)}}
async function offerLegacy(quiet=false){if(!cloud.user)return;const uid=cloud.user.uid,target=store,local=new LibraryStore();try{await local.open();if(target!==store){local.close();return}if(local.state.migration?.claimedBy&&local.state.migration.claimedBy!==uid){local.close();if(!quiet)notify('기존 기기 기록은 다른 계정에 연결되어 있어요.');return}if(!local.state.items.length&&!local.state.groups.length){local.close();if(!quiet)notify('연결할 이전 기기 기록이 없어요.');return}if(quiet&&local.state.migration?.claimedBy===uid){local.close();return}legacyOffer?.store?.close();legacyOffer={store:local,target,uid};showModal('이 기기의 기존 기록 연결',`<p class="reading">이 기기에 남아 있는 취향 ${local.state.items.length}개와 서랍 ${local.state.groups.length}개를 <strong>${e(cloud.user.email)}</strong> 계정으로 가져올까요?</p><p class="help">기존 원본은 그대로 보관합니다. 같은 ID가 이미 계정에 있으면 가져온 내용으로 바뀔 수 있으므로, 계정의 기존 기록이 있다면 먼저 전체 백업을 권장합니다.</p><div class="detail-controls">${button('이 계정으로 가져오기','adoptLegacy','primary')}${button('지금은 건너뛰기','skipLegacy')}</div>`)}catch(err){local.close();if(quiet)throw err;notify(err.message)}}
async function adoptLegacy(){const offer=legacyOffer;if(!offer||offer.uid!==cloud.user?.uid||offer.target!==store)throw Error('계정이 바뀌어 연결을 중단했어요.');const snapshot=await offer.store.export();if(offer.target!==store)throw Error('계정이 바뀌었어요.');await offer.target.safetyBackup('이전 기기 기록을 연결하기 전');if(offer.target!==store||offer.uid!==cloud.user?.uid)throw Error('계정이 바뀌어 연결을 취소했어요.');await offer.target.import(snapshot);if(offer.target!==store)throw Error('계정이 바뀌어 연결을 중단했어요.');await offer.target.mutate(s=>{s.migration={...offer.store.state.migration,claimedBy:offer.uid}});const original=await offer.store.original();if(original){const tx=offer.target.db.transaction('backups','readwrite');tx.objectStore('backups').put(original);await new Promise((res,rej)=>{tx.oncomplete=res;tx.onabort=()=>rej(tx.error)})}await offer.store.mutate(s=>{s.migration={...s.migration,claimedBy:offer.uid}});legacyOffer=null;offer.store.close();render();modal.close();cloud.changed();notify('기존 기록을 계정의 기기 보관함으로 가져왔어요. 계정 저장 상태를 확인해주세요.')}
function showConflict(){if(!cloud.conflict){notify(cloud.message||'해결할 저장 충돌이 없어요.');return}showModal('다른 기기의 기록과 차이가 있어요',`<p class="reading">어느 쪽도 자동으로 덮어쓰지 않았습니다. 선택 전 이 기기의 전체 백업을 다운로드할 수 있어요. 기록을 바꾸기 전 기기 안전 백업을 남기고 서버의 직전 버전도 보관합니다.</p><p class="help">서버: ${cloud.conflict.library?.items.length||0}개 항목 · 이 기기: ${store.state.items.length}개 항목</p><div class="menu-stack">${button('현재 기기 전체 백업 다운로드','export')}${button('서버 기록을 이 기기로 가져오기','useCloudRemote')}${button('이 기기 기록을 계정에 저장','useCloudLocal')}</div>`)}
async function safetyBackups(){const rows=(await store.safetyBackups()).filter(row=>row.library).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));showModal('이 계정의 기기 안전 백업',rows.map(row=>`<div class="trash-row"><div>${e(row.reason)}<small>${date(row.createdAt)} · ${row.library.items.length}개 항목</small></div>${button('다운로드','downloadSafety','small',`data-id="${e(row.id)}"`)}</div>`).join('')||'<p class="reading">아직 교체 전 안전 백업이 없어요. 서버 기록을 받거나 충돌을 해결할 때 자동으로 남깁니다.</p>')}
function cloudStatus(phase,message){let status=$('#cloudStatus');if(!status){status=document.createElement('button');status.id='cloudStatus';status.type='button';status.onclick=()=>phase==='conflict'?showConflict():settings();$('.topbar').insertBefore(status,$('#userMenu'))}status.dataset.phase=phase;status.textContent=({checking:'로그인 확인',connecting:'연결 중',pending:'저장 대기',syncing:'계정 저장 중',saved:'계정 저장됨',offline:'기기 저장',error:'계정 저장 확인 필요',conflict:'저장 충돌', 'signed-out':'로그인 필요'})[phase]||'저장 상태';status.title=message;status.onclick=()=>cloud.phase==='conflict'?showConflict():settings();$('#accountStatusText')?.replaceChildren(document.createTextNode(message))}
cloud=new AccountCloud({onAuth:accountReady,onStatus:cloudStatus,onRemote:()=>{blocked=false;render()},onConflict:()=>{if(!modal.open)showConflict();else notify('저장 충돌이 있어요. 편집을 마친 뒤 계정 설정에서 확인해주세요.')},isEditing:()=>modal.open||layoutDirty});lockApp(true);authGate('로그인 정보를 확인하고 있어요…');cloud.start();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(r=>r.update()).catch(()=>notify('오프라인 준비에 실패했어요. 온라인에서는 계속 사용할 수 있어요.')));

window.addEventListener('keydown',event=>{if(event.isComposing||modal.open||document.body.classList.contains('signed-out'))return;const typing=event.target.closest?.('input,textarea,select,[contenteditable=true]');if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'||!typing&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&event.key==='/'){event.preventDefault();const field=$('#globalSearch');field.focus();field.select()}});
